  const em = orm.em.fork();
  const authors = await em.find(Author, {}, { orderBy: { id: 'asc' } });
  const mock = mockLogger(orm);

  await em.populate(authors, ['books.publisher'], {
    strategy: 'select-in',
    where: {
      books: {
        $or: [{ publisher: { open: true } }, { author: { $in: [2] } }],
